  public void Request(string action){if(!IsVisible||leaving)return;if(action=="language"){languageMenu=!languageMenu;CancelGesture();if(practice)practice.Suspended=languageMenu||appPaused||!focused;Reflow(false);Focus(languageMenu?"locale-"+GameLocale.Current:"language");return;}if(action.StartsWith("locale:",StringComparison.Ordinal)){int i;if(int.TryParse(action.Substring(7),out i)&&GameLocale.Valid(i)){GameLocale.Select(i);PlayerPrefs.SetInt(GameLocale.PreferenceKey,i);PlayerPrefs.Save();languageMenu=false;if(practice)practice.Suspended=appPaused||!focused;Reflow(false);Focus("language");}return;}if(languageMenu)return;if(action=="music"){settings.Toggle("music");music.mute=!settings.Music;Reflow(false);Focus("music");return;}if(action=="skip"){session.Skip();ShowStage();return;}if(action=="retry"){session.Retry();ShowStage();return;}if(action=="next"){bool launch=session.Stage==FirstStartStage.Ready;if(session.Next()){if(launch)Leave(true);else ShowStage();}return;}if(action.StartsWith("cell:",StringComparison.Ordinal)){var p=action.Substring(5).Split(',');Tap(int.Parse(p[0]),int.Parse(p[1]));}}
