  public void PointerDown(PointerEventData e){if(languageMenu||session==null||!session.Practice||session.Busy)return;pointers.Add(e.pointerId);if(pointers.Count>1){multiTouch=true;dragOwner=int.MinValue;allowedClick=int.MinValue;return;}if(multiTouch)return;allowedClick=int.MinValue;dragOwner=e.pointerId;press=e.position;dragged=false;}
