  void CancelGesture(){dragOwner=allowedClick=int.MinValue;dragged=false;multiTouch=false;pointers.Clear();}
  void Leave(bool launch){if(leaving)return;leaving=true;CancelGesture();if(practice)practice.Release();if(music){music.Stop();Destroy(music);}if(ownedListener){ownedListener.enabled=false;Destroy(ownedListener);}canvas.gameObject.SetActive(false);home.SetPresentation(true,true);if(launch){var flow=home.GetComponent<HomeLevelFlow>();if(flow)flow.Open(home.State.currentLevel);}}
  float Scale(Rect sr)=>Mathf.Min(home.CurrentUIScale,Mathf.Max(.35f,sr.width/320f),Mathf.Max(.35f,sr.height/360f));
  void Update(){if(!IsVisible||session==null)return;Rect sr=Screen.safeArea;if(sr.width<=0)sr=new Rect(0,0,Screen.width,Screen.height);float scale=Scale(sr);if(screen.x!=Screen.width||screen.y!=Screen.height||lastSafe!=sr||Mathf.Abs(scale-lastScale)>.01f||localeRevision!=GameLocale.Revision){CancelGesture();Reflow(false);}fade.alpha=home.State.reduceMotion?1:Mathf.Clamp01((Time.unscaledTime-opened)/.35f);if(backdrop&&!home.State.reduceMotion&&!appPaused&&focused){float z=1+.014f*Mathf.Sin((Time.unscaledTime-opened)*.12f);backdrop.uvRect=new Rect(baseUV.center.x-baseUV.width/(2*z),baseUV.center.y-baseUV.height/(2*z),baseUV.width/z,baseUV.height/z);}RevealSelected();
