  void Reflow(bool reset){if(!canvas)return;float position=reset?1:scroll.verticalNormalizedPosition;string focus="";if(EventSystem.current&&EventSystem.current.currentSelectedGameObject){var a=EventSystem.current.currentSelectedGameObject.GetComponent<HomeControlLabel>();if(a)focus=a.action;}foreach(var root in new[]{chrome,content,overlay})foreach(Transform child in root){child.gameObject.SetActive(false);Destroy(child.gameObject);}nodes.Clear();Rect sr=Screen.safeArea;if(sr.width<=0)sr=new Rect(0,0,Screen.width,Screen.height);float scale=Scale(sr);scaler.scaleFactor=scale;canvas.scaleFactor=scale;Place(safe,sr.x/scale,(Screen.height-sr.yMax)/scale,sr.width/scale,sr.height/scale);var f=FirstStartLayout.Build(sr.width/scale,sr.height/scale,session,opening,settings.Music,languageMenu,status);Place(chrome,0,0,f.width,f.height);Place(overlay,0,0,f.width,f.height);Place(viewport,f.viewportX,f.viewportY,f.viewportWidth,f.viewportHeight);Place(content,0,0,f.content.width,f.content.height);Render(f.chrome,chrome);Render(f.content,content);Render(f.overlay,overlay);overlay.gameObject.SetActive(languageMenu);foreach(var root in new[]{chrome,content}){var group=root.GetComponent<CanvasGroup>();group.interactable=group.blocksRaycasts=!languageMenu;}Canvas.ForceUpdateCanvases();scroll.verticalNormalizedPosition=position;screen=new Vector2Int(Screen.width,Screen.height);lastSafe=sr;lastScale=scale;localeRevision=GameLocale.Revision;if(focus!="")foreach(var pair in nodes){var a=pair.Value.GetComponent<HomeControlLabel>();if(a&&a.action==focus){Focus(pair.Key);break;}}}
  void Render(HomeFrame frame,RectTransform root){foreach(var e in frame.elements){var parent=string.IsNullOrEmpty(e.parent)?root:nodes[e.parent];var rt=Rect(e.id,parent);Place(rt,e.x,e.y,e.width,e.height);nodes[e.id]=rt;
