  void Button(RectTransform rt,string action,string label){var im=rt.gameObject.AddComponent<Image>();im.color=Color.clear;Button b;if(action.StartsWith("cell:",StringComparison.Ordinal)){var cb=rt.gameObject.AddComponent<PracticeCellButton>();cb.owner=this;b=cb;}else b=rt.gameObject.AddComponent<Button>();b.targetGraphic=im;b.transition=Selectable.Transition.None;b.interactable=action!="disabled";b.onClick.AddListener(()=>Request(action));var a=rt.gameObject.AddComponent<HomeControlLabel>();a.action=action;a.label=label;}
