  GameObject priorFocus;void RevealSelected(){if(!EventSystem.current)return;var go=EventSystem.current.currentSelectedGameObject;if(!go||go==priorFocus)return;priorFocus=go;var rt=go.transform as RectTransform;if(!rt||!rt.IsChildOf(content))return;Canvas.ForceUpdateCanvases();var bounds=RectTransformUtility.CalculateRelativeRectTransformBounds(viewport,rt);float top=viewport.rect.yMax,bottom=viewport.rect.yMin,delta=bounds.max.y>top?bounds.max.y-top:bounds.min.y<bottom?bounds.min.y-bottom:0;var p=content.anchoredPosition;p.y=Mathf.Clamp(p.y+delta,0,Mathf.Max(0,content.rect.height-viewport.rect.height));content.anchoredPosition=p;}
